769	  fld.removeAttribute('data-k');
770	  let f = 0;
771	  const on = () => { if (!f) f = requestAnimationFrame(() => { f = 0; paint(t()); }); };
772	  addEventListener('scroll', on, { passive: true });
773	  addEventListener('resize', on, { passive: true });
774	  document.fonts.ready.then(on);     // Cormorant swap changes scrollHeight
