792	.fld .w rect { fill: var(--color-paper); stroke: currentColor; stroke-width: 1;
793	               stroke-opacity: var(--fog); }
794	.fld .w path { fill: none; stroke: currentColor; stroke-width: 1;
795	               stroke-opacity: var(--fog); }
796	
797	/* the chains */
798	.fld .r rect { fill: var(--color-paper); stroke: currentColor; stroke-width: 1;
799	               stroke-opacity: .30;
800	               transition: stroke-opacity var(--dur-lit) var(--ease-out); }
801	.fld .r path { fill: none; stroke: currentColor; stroke-width: 1;
802	               stroke-opacity: var(--dim);
803	               transition: stroke-opacity var(--dur-lit) var(--ease-out); }
804	
805	/* no-JS and reduced-motion default: a complete, legible, calm image */
806	.fld[data-k="all"] .r path { stroke-opacity: var(--near); }
807	.fld[data-k="all"] .r rect { stroke-opacity: .60; }
808	
809	/* six steps — the current chain lit, the previous one held, the rest dim */
810	.fld[data-k="0"] .r .c0 { stroke-opacity: var(--lit);  }
811	.fld[data-k="0"] .r rect.c0 { stroke-opacity: 1; }
812	.fld[data-k="1"] .r .c1 { stroke-opacity: var(--lit);  }
813	.fld[data-k="1"] .r rect.c1 { stroke-opacity: 1; }
814	.fld[data-k="1"] .r .c0 { stroke-opacity: var(--near); }
815	.fld[data-k="1"] .r rect.c0 { stroke-opacity: var(--near); }
816	/* … k = 2 … 5, identical quadruples … */
817	```
