#!/usr/bin/env node
// Seeded generator for the field's wash layer (WINNER.md §6.5).
// Lives OUTSIDE the target repo on purpose: outputDirectory "." ships every file,
// and a generator carrying descriptive comments would be a shipped description.
// Emits only geometry + indices. Run once, commit the output markup.

const SEED = Number(process.argv[2] || 20260807)

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const N = 10               // mark size
const CLEAR = 24           // required clearance
const XMIN = 20, XMAX = 1410
const YMIN = 30, YMAX = 860

// Chain marks (§6.6) — the wash must keep CLEAR from all of these.
const CHAIN_MARKS = [
  [40, 68], [128, 140], [60, 236],
  [1392, 140], [1300, 228], [1380, 332],
  [36, 332], [124, 404], [52, 500],
  [1372, 428], [1292, 512], [1400, 620],
  [44, 572], [140, 656], [68, 772],
  [1340, 652], [1276, 736], [1368, 840],
]

// Chain wires reduced to axis-aligned segments [x1,y1,x2,y2] for clearance tests.
const CHAIN_SEGS = [
  [45, 78, 45, 145], [45, 145, 128, 145], [133, 150, 133, 241], [133, 241, 70, 241],
  [1392, 145, 1305, 145], [1305, 145, 1305, 228], [1305, 238, 1305, 337], [1305, 337, 1380, 337],
  [46, 337, 129, 337], [129, 337, 129, 404], [129, 414, 129, 505], [129, 505, 62, 505],
  [1372, 433, 1297, 433], [1297, 433, 1297, 512], [1297, 522, 1297, 625], [1297, 625, 1400, 625],
  [54, 577, 145, 577], [145, 577, 145, 656], [145, 666, 145, 777], [145, 777, 78, 777],
  [1340, 657, 1281, 657], [1281, 657, 1281, 736], [1281, 746, 1281, 840], [1281, 840, 1368, 840],
  [1373, 850, 1373, 940],
]

const snap4 = (v) => Math.round(v / 4) * 4

// distance from axis-aligned rect (x,y,N,N) to a segment, 0 if intersecting
function rectSegDist(rx, ry, seg) {
  const [x1, y1, x2, y2] = seg
  const sx = Math.min(x1, x2), ex = Math.max(x1, x2)
  const sy = Math.min(y1, y2), ey = Math.max(y1, y2)
  const dx = Math.max(sx - (rx + N), rx - ex, 0)
  const dy = Math.max(sy - (ry + N), ry - ey, 0)
  return Math.hypot(dx, dy)
}

function rectRectDist(ax, ay, bx, by) {
  const dx = Math.max(bx - (ax + N), ax - (bx + N), 0)
  const dy = Math.max(by - (ay + N), ay - (by + N), 0)
  return Math.hypot(dx, dy)
}

function generate(seed) {
  const rnd = mulberry32(seed)
  const marks = []
  let guard = 0
  while (marks.length < 34 && guard++ < 200000) {
    const x = snap4(XMIN + rnd() * (XMAX - XMIN))
    const y = snap4(YMIN + rnd() * (YMAX - YMIN))
    if (x < XMIN || x > XMAX || y < YMIN || y > YMAX) continue
    if (y + N > 870) continue                                        // constraint 6
    if (CHAIN_MARKS.some(([cx, cy]) => rectRectDist(x, y, cx, cy) < CLEAR)) continue  // 2
    if (CHAIN_SEGS.some((s) => rectSegDist(x, y, s) < CLEAR)) continue                // 2
    if (marks.some(([mx, my]) => rectRectDist(x, y, mx, my) < CLEAR)) continue        // 3
    // constraint 4 — at most 6 marks in any 200x200 region
    const dense = marks.filter(([mx, my]) => Math.abs(mx - x) < 200 && Math.abs(my - y) < 200)
    if (dense.length >= 6) continue
    marks.push([x, y])
  }
  return marks.length === 34 ? marks : null
}

// Orthogonal router with a single 10-unit fillet, matching ptl-trade's ROUTE_CORNER_RADIUS.
function route(a, b) {
  const [ax, ay] = a, [bx, by] = b
  const acx = ax + N / 2, bcx = bx + N / 2
  const acy = ay + N / 2, bcy = by + N / 2
  const out = []
  // vertical first, then horizontal
  if (Math.abs(by - ay) > 30 && Math.abs(bx - ax) > 30) {
    const down = by > ay
    const sy = down ? ay + N : ay
    const ey = bcy
    const right = bx > ax
    const ex = right ? bx : bx + N
    const preY = down ? ey - 10 : ey + 10
    const fx = right ? acx + 10 : acx - 10
    if (Math.abs(preY - sy) > 6 && Math.abs(ex - fx) > 6) {
      out.push(`M ${acx} ${sy} V ${preY} Q ${acx} ${ey} ${fx} ${ey} H ${ex}`)
    }
    // horizontal first, then vertical
    const sx = right ? ax + N : ax
    const exq = bcx
    const preX = right ? exq - 10 : exq + 10
    const fy = down ? acy + 10 : acy - 10
    const eyq = down ? by : by + N
    if (Math.abs(preX - sx) > 6 && Math.abs(eyq - fy) > 6) {
      out.push(`M ${sx} ${acy} H ${preX} Q ${exq} ${acy} ${exq} ${fy} V ${eyq}`)
    }
  }
  return out
}

function pickWires(marks, seed) {
  const rnd = mulberry32(seed ^ 0x9e3779b9)
  const manhattan = (a, b) => Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1])
  const cands = []
  for (let i = 0; i < marks.length; i++) {
    for (let j = i + 1; j < marks.length; j++) {
      const d = manhattan(marks[i], marks[j])
      if (d > 60 && d <= 180) {
        const paths = route(marks[i], marks[j])
        if (paths.length) cands.push({ i, j, d, path: paths[Math.floor(rnd() * paths.length)] })
      }
    }
  }
  cands.sort((p, q) => p.d - q.d)
  const used = new Set()
  const pairs = []
  for (const c of cands) {
    if (pairs.length >= 4) break
    if (used.has(c.i) || used.has(c.j)) continue
