// segments of an emitted path, for wire-vs-wire overlap tests
function pathSegs(d) {
  const t = d.split(/\s+/)
  const segs = []
  let x = 0, y = 0, i = 0
  while (i < t.length) {
    const op = t[i]
    if (op === 'M') { x = +t[i + 1]; y = +t[i + 2]; i += 3 }
    else if (op === 'V') { segs.push([x, y, x, +t[i + 1]]); y = +t[i + 1]; i += 2 }
    else if (op === 'H') { segs.push([x, y, +t[i + 1], y]); x = +t[i + 1]; i += 2 }
    else if (op === 'Q') { x = +t[i + 3]; y = +t[i + 4]; i += 5 }
    else i++
  }
  return segs
}

function segSegDist(a, b) {
  const ax1 = Math.min(a[0], a[2]), ax2 = Math.max(a[0], a[2])
  const ay1 = Math.min(a[1], a[3]), ay2 = Math.max(a[1], a[3])
  const bx1 = Math.min(b[0], b[2]), bx2 = Math.max(b[0], b[2])
  const by1 = Math.min(b[1], b[3]), by2 = Math.max(b[1], b[3])
  const dx = Math.max(bx1 - ax2, ax1 - bx2, 0)
  const dy = Math.max(by1 - ay2, ay1 - by2, 0)
  return Math.hypot(dx, dy)
}

