@import "tailwindcss";

@theme {
  --color-paper: rgb(250 248 245);
  --color-ink: rgb(30 30 30);
  --color-reading: rgb(64 64 64);
  --color-muted-text: rgb(112 112 112);
  --color-muted-mark: rgb(115 115 115);
  --color-hairline: rgb(200 200 200);
  --color-hairline-soft: rgb(200 200 200 / 0.6);
  --color-ring: rgb(115 115 115);

  --font-sans: "Cormorant", ui-serif, Georgia, serif;
  --font-serif: "Cormorant", ui-serif, Georgia, serif;
  --font-mono: "Geist Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

  --radius: 0;

  --dur-fast: 150ms;
  --dur-lit: 300ms;
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);

  --measure: 34rem;
  --gutter: 5rem;
  --rail: 17rem;
  --page: 56rem;
}

/* ---------------------------------------------------------------------------
   Base. Page styles below are deliberately UNLAYERED: this page uses semantic
   classes rather than utilities, and unlayered author styles beat @layer
   utilities regardless of specificity. That cascade fact previously destroyed
   the body size and the wordmark's second line here.
--------------------------------------------------------------------------- */

@layer base {
  html {
    font-size: 100%;
    scrollbar-gutter: stable both-edges;
    overscroll-behavior: contain;
    overscroll-behavior-y: contain;
  }

  body {
    margin: 0;
    background: var(--color-paper);
    color: var(--color-reading);
    font-family: var(--font-sans);
    overscroll-behavior: contain;
    overscroll-behavior-y: contain;
    -webkit-text-size-adjust: 100%;
  }

  ::selection {
    background: rgb(30 30 30 / 0.1);
  }

  :focus-visible {
    outline: 1px solid var(--color-ring);
    outline-offset: 3px;
  }
}

/* --- layout ------------------------------------------------------------- */

.shell {
  position: relative;
  z-index: 1;
  padding: 5rem 1.5rem 88px;
}

.page {
  max-width: var(--measure);
  margin-inline: auto;
}

@media (min-width: 64rem) {
  .shell {
    padding-inline: 2rem;
  }
  .page {
    display: grid;
    grid-template-columns: var(--measure) var(--rail);
    column-gap: var(--gutter);
    max-width: var(--page);
  }
  .col-argument {
    grid-column: 1;
  }
  .col-rail {
    grid-column: 2;
    grid-row: 6;
  }
}

.beat + .beat,
.beat + .close-block {
  margin-top: 64px;
}

@media (max-width: 39.99rem) {
  .beat + .beat,
  .beat + .close-block {
    margin-top: 48px;
  }
}

/* --- masthead ----------------------------------------------------------- */

.masthead {
  border-bottom: 1px solid var(--color-hairline);
  padding-bottom: 16px;
  margin-bottom: 64px;
}

.wordmark-1 {
  font-size: clamp(3.5rem, 9vw, 6rem);
  font-weight: 500;
  letter-spacing: 0.05em;
  line-height: 1;
  color: var(--color-ink);
  margin: 0;
}

.wordmark-2-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 4px;
}

.wordmark-2 {
  font-size: clamp(1.75rem, 4.5vw, 3rem);
  font-style: italic;
  font-weight: 300;
  letter-spacing: 0.02em;
  line-height: 1.1;
  color: var(--color-ink);
  margin: 0;
}

.handle {
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.02em;
  line-height: 1.2;
  color: var(--color-muted-text);
  white-space: nowrap;
}

/* --- type roles --------------------------------------------------------- */

.statement {
  font-size: 30px;
  font-weight: 400;
  line-height: 1.35;
  color: var(--color-ink);
  margin: 0;
}

.label-micro {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--color-muted-text);
  margin: 0 0 16px;
}

.body-text {
  font-size: 22px;
  font-weight: 400;
  line-height: 1.5;
  color: var(--color-reading);
  margin: 0;
}

.body-text + .body-text {
  margin-top: 24px;
}

.gloss {
  font-size: 22px;
  font-style: italic;
  font-weight: 300;
  line-height: 1.5;
  color: var(--color-muted-text);
  margin: 0 0 12px;
}

@media (max-width: 39.99rem) {
  .statement {
    font-size: 24px;
  }
  .body-text,
  .gloss {
    font-size: 20px;
  }
  .body-text + .body-text {
    margin-top: 20px;
  }
}

/* --- the strip ---------------------------------------------------------- */

.strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0 24px;
  border-block: 1px solid var(--color-hairline);
  padding-block: 14px;
  margin: 24px 0 0;
}

.strip dt {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--color-muted-text);
}

.strip dd {
  margin: 8px 0 0;
  font-size: 22px;
  line-height: 1.3;
  color: var(--color-reading);
}

.strip .dash {
  font-family: var(--font-mono);
  font-size: 20px;
  font-weight: 500;
  color: var(--color-muted-text);
}

.strip-caption {
  font-size: 16px;
  line-height: 1.45;
  color: var(--color-reading);
  margin: 12px 0 0;
}

@media (max-width: 39.99rem) {
  .strip dd {
    font-size: 16px;
  }
}

/* --- the loop band ------------------------------------------------------ */

.band {
  border-block: 1px solid var(--color-hairline);
  padding-block: 12px;
  margin: 24px 0;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--color-muted-text);
}

/* --- contact ------------------------------------------------------------ */

.contact {
  border-top: 1px solid var(--color-hairline);
  padding-top: 14px;
  margin-top: 24px;
}

.contact a {
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 500;
  color: var(--color-ink);
  text-decoration: none;
  border-bottom: 1px solid var(--color-hairline);
  padding-bottom: 2px;
  transition: border-color var(--dur-fast) var(--ease-standard);
}

.contact a:hover {
  border-bottom-color: var(--color-ink);
}

/* --- roster ------------------------------------------------------------- */

.col-rail {
  margin-top: 64px;
}

@media (min-width: 64rem) {
  .col-rail {
    margin-top: 0;
  }
}

.roster-group + .roster-group {
  margin-top: 32px;
}

.roster-label {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  line-height: 1.2;
  text-transform: uppercase;
  color: var(--color-muted-text);
  border-bottom: 1px solid var(--color-hairline-soft);
  padding-bottom: 8px;
  margin: 0 0 16px;
}

.roster-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.roster-list li + li {
  margin-top: 16px;
}

.roster-name {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.45;
  color: var(--color-ink);
}

.roster-handle {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-muted-text);
  margin-left: 12px;
}

.roster-bio {
  font-size: 16px;
  font-weight: 400;
  line-height: 1.45;
  color: var(--color-muted-text);
  margin: 4px 0 0;
}

/* --- ground bloom, field, footer band ----------------------------------- */

.bloom {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  --oval-rx: 100vw;
  --oval-ry: 8rem;
  background: radial-gradient(
    ellipse var(--oval-rx) var(--oval-ry) at 50% 96%,
    rgb(255 255 255 / 0.85) 0%,
    rgb(255 255 255 / 0.72) 45%,
    rgb(255 255 255 / 0.4) 65%,
    rgb(255 255 255 / 0.16) 82%,
    rgb(255 255 255 / 0) 100%
  );
}

@media (min-width: 64rem) {
  .bloom {
    --oval-ry: 10rem;
  }
}

.fld {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  color: var(--color-ink);
  --dim: 0.06;
  --fog: 0.18;
  --near: 0.45;
  --lit: 1;
}

.fld .w rect,
.fld .r rect {
  fill: var(--color-paper);
  stroke: currentColor;
  stroke-width: 1;
}

.fld .w path,
.fld .r path {
  fill: none;
  stroke: currentColor;
  stroke-width: 1;
  stroke-linecap: butt;
}

.fld .w rect,
.fld .w path {
  stroke-opacity: var(--fog);
}

.fld .r rect {
  stroke-opacity: 0.3;
  transition: stroke-opacity var(--dur-lit) var(--ease-out);
}

.fld .r path {
  stroke-opacity: var(--dim);
  transition: stroke-opacity var(--dur-lit) var(--ease-out);
}

/* no-JS and reduced-motion ship state: a complete, calm, legible image */
.fld[data-k="all"] .r path {
  stroke-opacity: var(--near);
}
.fld[data-k="all"] .r rect {
  stroke-opacity: 0.6;
}

.fld[data-k="0"] .r .c0,
.fld[data-k="1"] .r .c1,
.fld[data-k="2"] .r .c2,
.fld[data-k="3"] .r .c3,
.fld[data-k="4"] .r .c4,
.fld[data-k="5"] .r .c5 {
  stroke-opacity: var(--lit);
}

.fld[data-k="1"] .r .c0,
.fld[data-k="2"] .r .c1,
.fld[data-k="3"] .r .c2,
.fld[data-k="4"] .r .c3,
.fld[data-k="5"] .r .c4 {
  stroke-opacity: var(--near);
}

/* chains only exist where they clear the 896px page block */
@media (max-width: 79.99rem) {
  .fld .r {
    display: none;
  }
}

.footer-band {
  position: fixed;
  inset-inline: 0;
  bottom: 0;
  z-index: 3;
  background: var(--color-paper);
  border-top: 1px solid var(--color-hairline);
  padding: 10px 16px;
  padding-bottom: 10px;
  padding-bottom: calc(10px + env(safe-area-inset-bottom));
  text-align: center;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.08em;
  line-height: 1.2;
  font-variant-numeric: tabular-nums lining-nums;
  color: var(--color-muted-text);
}

/* --- a11y --------------------------------------------------------------- */

.vh {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .fld .r rect,
  .fld .r path {
    transition: none;
  }
  .contact a {
    transition: none;
  }
}

