// The 896px page block is centred, spanning viewBox x in [272,1168] at 1440x900
// and widening as the viewport narrows. Wires must never cross it: a 1px
// orthogonal line behind 22px Cormorant reads as a strikethrough. Marks may sit
// anywhere (at 0.18 they are fainter than the page's own hairlines); wires may
// only live in these outer bands.
const BAND_L = 260
const BAND_R = 1180
const inBand = (x) => x + N <= BAND_L || x >= BAND_R

function generate(seed) {
  const rnd = mulberry32(seed)
  const marks = []
  let guard = 0
  // Seed the margins first so there is enough material out there to wire.
  const MARGIN_QUOTA = 12
  while (marks.length < 34 && guard++ < 400000) {
    const wantMargin = marks.length < MARGIN_QUOTA
    let x = snap4(XMIN + rnd() * (XMAX - XMIN))
    const y = snap4(YMIN + rnd() * (YMAX - YMIN))
    if (wantMargin) {
      x = rnd() < 0.5
        ? snap4(XMIN + rnd() * (BAND_L - N - XMIN))
        : snap4(BAND_R + rnd() * (XMAX - BAND_R))
    }
    if (x < XMIN || x > XMAX || y < YMIN || y > YMAX) continue
    if (wantMargin && !inBand(x)) continue

