input.new_string:
const cands = []
for (let i = 0; i < marks.length; i++) {
  for (let j = i + 1; j < marks.length; j++) {
    // both endpoints must sit in the same outer band
    if (!inBand(marks[i][0]) || !inBand(marks[j][0])) continue
    if ((marks[i][0] < BAND_L) !== (marks[j][0] < BAND_L)) continue
    const d = manhattan(marks[i], marks[j])
    if (d > 60 && d <= 180) {
      const paths = route(marks[i], marks[j])
      for (const p of paths) {
        // and every vertex of the routed path must stay in the band too
        const xs = pathSegs(p).flatMap((s) => [s[0], s[2]])
        const ok = xs.every((x) => (marks[i][0] < BAND_L ? x <= BAND_L : x >= BAND_R))
        if (ok) { cands.push({ i, j, d, path: p }); break }
      }
    }
  }
}

