/* =========================================================================
   PTL house language — values sampled directly from product screenshots,
   not invented. Shared by all three option pages.
   ========================================================================= */

@font-face {
  font-family: "Cormorant";
  src: url("fonts/Cormorant Variable Font.woff2") format("woff2-variations");
  font-weight: 300 700; font-style: normal; font-display: swap;
}
@font-face {
  font-family: "Cormorant";
  src: url("fonts/Cormorant Italic Variable Font.woff2") format("woff2-variations");
  font-weight: 300 700; font-style: italic; font-display: swap;
}
@font-face {
  font-family: "Geist Mono";
  src: url("fonts/GeistMono.woff2") format("woff2");
  font-weight: 100 900; font-style: normal; font-display: swap;
}

:root {
  /* neutrals — #141414/#1e1e1e/#3c3c3c/#f0f0f0 appear in all three apps */
  --ground:    #141414;
  --ground-2:  #121212;
  --panel:     #1e1e1e;
  --panel-2:   #282828;
  --hair:      #3c3c3c;
  --hair-soft: #262626;
  --ink:       #f0f0f0;
  --ink-2:     #a0a0a0;
  --ink-3:     #818181;
  --cream:     #ffebb4;

  /* taxonomy triads — border / fill / ink, built the way ptl-trade builds them */
  --slate-b: #3c3c3c; --slate-f: #1a1a1a; --slate-i: #a0a0a0;
  --blue-b:  #1447e6; --blue-f:  #141d2a; --blue-i:  #2b7fff;
  --amber-b: #bb4d00; --amber-f: #22140e; --amber-i: #f08610;
  --green-b: #008236; --green-f: #0e1b14; --green-i: #00c950;

  --serif: "Cormorant", ui-serif, Georgia, serif;
  --mono:  "Geist Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

  --measure: 40rem;
  --bar-top: 52px;
  --bar-bot: 46px;

  --ease: cubic-bezier(0.16, 1, 0.3, 1);
  --dur:  420ms;
}

* { box-sizing: border-box; }

html {
  background: var(--ground);
  scrollbar-gutter: stable;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--ground);
  color: var(--ink-2);
  font-family: var(--serif);
  font-variant-numeric: tabular-nums lining-nums;
  -webkit-font-smoothing: antialiased;
}

::selection { background: rgb(240 240 240 / 0.16); }
:focus-visible { outline: 1px solid var(--ink-3); outline-offset: 3px; }

/* --- chrome: the two fixed bars, straight out of the trade app ----------- */

.topbar {
  position: fixed; inset-inline: 0; top: 0; z-index: 40;
  height: var(--bar-top);
  display: flex; align-items: center; justify-content: space-between;
  gap: 1rem;
  padding: 0 20px;
  background: var(--ground-2);
  border-bottom: 1px solid var(--hair);
}

.wordmark {
  font-family: var(--serif);
  font-style: italic;
  font-weight: 500;
  font-size: 20px;
  line-height: 1;
  color: var(--ink);
  letter-spacing: 0.01em;
}

.topbar .id {
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--ink-3);
}

/* the loop strip — the RISK BUDGET strip's form, carrying the argument */
.loopbar {
  position: fixed; inset-inline: 0; bottom: 0; z-index: 40;
  height: var(--bar-bot);
  display: flex; align-items: center;
  gap: 0;
  padding: 0 20px;
  padding-bottom: env(safe-area-inset-bottom);
  background: var(--ground-2);
  border-top: 1px solid var(--hair);
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.loopbar .lb-label {
  color: var(--ink-3);
  margin-right: 18px;
  white-space: nowrap;
}

.loop-steps { display: flex; align-items: center; gap: 0; flex: 1; min-width: 0; }

.step {
  display: flex; align-items: center; gap: 8px;
  color: #4a4a4a;
  transition: color var(--dur) var(--ease);
  white-space: nowrap;
}
.step .dot {
  width: 6px; height: 6px;
  background: #333;
  transition: background var(--dur) var(--ease);
  flex: none;
}
.step .rule {
  width: clamp(14px, 4vw, 56px); height: 1px;
  background: #2e2e2e;
  margin: 0 12px;
  transition: background var(--dur) var(--ease);
  flex: none;
}
.step.on { color: var(--hue-i, var(--ink)); }
.step.on .dot { background: var(--hue-i, var(--ink)); }
.step.on .rule { background: var(--hue-b, var(--hair)); }

.loopbar .lb-state {
  margin-left: auto;
  color: var(--ink-3);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

/* --- shell -------------------------------------------------------------- */

.shell {
  position: relative; z-index: 10;
  padding: calc(var(--bar-top) + 96px) 20px calc(var(--bar-bot) + 96px);
}
.col {
  max-width: var(--measure);
  margin-inline: auto;
}

/* --- type roles --------------------------------------------------------- */

.statement {
  font-family: var(--serif);
  font-size: clamp(30px, 4.2vw, 46px);
  font-weight: 400;
  line-height: 1.24;
  letter-spacing: -0.005em;
  color: var(--ink);
  margin: 0;
  text-wrap: balance;
}

.micro {
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
  margin: 0;
}

.body {
  font-family: var(--serif);
  font-size: 21px;
  font-weight: 400;
  line-height: 1.52;
  color: var(--ink-2);
  margin: 0;
}
.body + .body { margin-top: 18px; }
.body em, .gloss { font-style: italic; color: var(--ink-3); }

.gloss {
  font-family: var(--serif);
  font-size: 19px;
  font-weight: 300;
  line-height: 1.5;
  margin: 0 0 14px;
}

/* --- the pill — trade's ARMED / WATCH / LIVE chip ------------------------ */

.pill {
  display: inline-flex; align-items: center;
  font-family: var(--mono);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 4px 8px;
  color: var(--hue-i, var(--ink-3));
  background: var(--hue-f, #1a1a1a);
  border: 1px solid var(--hue-b, var(--hair));
  white-space: nowrap;
}
.pill.empty {
  color: var(--ink-3);
  background: transparent;
  border-style: dashed;
  border-color: #333;
  letter-spacing: 0;
  font-size: 12px;
  padding: 3px 10px;
}

/* --- the panel — trade's thesis card ------------------------------------ */

.panel {
  position: relative;
  border: 1px solid var(--hair-soft);
  background: #171717;
  padding: 22px 24px 24px;
  transition: border-color var(--dur) var(--ease),
              background-color var(--dur) var(--ease),
              opacity var(--dur) var(--ease);
  opacity: 0.34;
}
.panel-head {
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

/* lit state — the hue arrives with the reader */
.panel.lit {
  opacity: 1;
  border-color: var(--hue-b, var(--hair));
  background: var(--hue-f, var(--panel));
}
.panel.seen { opacity: 0.5; }

/* the terminal panel: bordered, dashed, deliberately empty */
.panel.withheld {
  background: transparent;
  border-style: dashed;
  border-color: #333;
}
.panel.withheld.lit { border-color: #4a4a4a; background: transparent; }

/* --- strip: micro-label over value on a hairline rule -------------------- */

.strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0 20px;
  border-block: 1px solid var(--hair-soft);
  padding-block: 13px;
  margin-top: 22px;
}
.strip dt {
  font-family: var(--mono);
  font-size: 10px; font-weight: 500;
  letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--ink-3);
}
.strip dd {
  margin: 9px 0 0;
  font-family: var(--serif);
  font-size: 19px; line-height: 1.3;
  color: var(--ink-2);
}
.strip .absent {
  font-family: var(--mono);
  font-size: 18px; font-weight: 500;
  color: var(--ink-3);
}
.cap {
  font-family: var(--serif);
  font-style: italic;
  font-size: 15px; line-height: 1.45;
  color: var(--ink-3);
  margin: 12px 0 0;
}

/* --- roster ------------------------------------------------------------- */

.roster { display: grid; gap: 40px; }
@media (min-width: 60rem) { .roster { grid-template-columns: 1.4fr 1fr; gap: 56px; } }

.roster h3 {
  font-family: var(--mono);
  font-size: 10px; font-weight: 500;
  letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--ink-3);
  border-bottom: 1px solid var(--hair-soft);
  padding-bottom: 9px;
  margin: 0 0 16px;
}
.roster ul { list-style: none; margin: 0; padding: 0; }
.roster li + li { margin-top: 15px; }
.r-name {
  font-family: var(--serif);
  font-size: 18px; font-weight: 600; line-height: 1.35;
  color: var(--ink);
}
.r-handle {
  font-family: var(--mono);
  font-size: 9.5px; font-weight: 500;
  letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--ink-3);
  margin-left: 11px;
}
.r-bio {
  font-family: var(--serif);
  font-size: 16px; line-height: 1.45;
  color: var(--ink-3);
  margin: 3px 0 0;
}

/* --- contact ------------------------------------------------------------ */

.contact { border-top: 1px solid var(--hair-soft); padding-top: 14px; margin-top: 26px; }
.contact a {
  font-family: var(--mono);
  font-size: 15px; font-weight: 500;
  color: var(--ink);
  text-decoration: none;
  border-bottom: 1px solid var(--hair);
  padding-bottom: 2px;
  transition: border-color 150ms var(--ease), color 150ms var(--ease);
}
.contact a:hover { border-bottom-color: var(--green-i); color: var(--green-i); }

/* --- rhythm ------------------------------------------------------------- */

.beat + .beat, .hero + .beat, .beat + .closing, .closing + .beat { margin-top: 88px; }
@media (max-width: 48rem) {
  .beat + .beat, .hero + .beat, .beat + .closing, .closing + .beat { margin-top: 64px; }
  .body { font-size: 19px; }
  .strip { grid-template-columns: 1fr; gap: 12px 0; }
  .strip dd { margin-top: 4px; }
}

.vh {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0;
}

@media (prefers-reduced-motion: reduce) {
  * { transition-duration: 1ms !important; animation-duration: 1ms !important; }
  .panel { opacity: 1; }
}

