// Zero-dependency live-reload preview server for the prototypes.
// Watches this directory and pushes a reload over SSE on any save.
// The reload snippet is injected at serve time and never written to disk.
//
//   node proto/dev.mjs [port]

import { createServer } from 'node:http'
import { readFile, stat } from 'node:fs/promises'
import { watch } from 'node:fs'
import { extname, join, normalize, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = resolve(fileURLToPath(new URL('.', import.meta.url)))
const PORT = Number(process.argv[2] || 5410)

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.woff2': 'font/woff2',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.json': 'application/json',
}

const SNIPPET = `<script>
(function(){
  var es = new EventSource('/__reload')
  es.onmessage = function(){ location.reload() }
  es.onerror = function(){ /* server restarting; EventSource retries on its own */ }
})()
</script>`

/** open SSE responses */
const clients = new Set()

let timer = null
watch(ROOT, { recursive: true }, (_e, name) => {
  if (!name || name === 'dev.mjs' || name.startsWith('.')) return
  clearTimeout(timer)
  // editors write in bursts (temp file, rename, chmod) — collapse them
  timer = setTimeout(() => {
    console.log(`  reload  ${name}`)
    for (const res of clients) res.write('data: reload\n\n')
  }, 60)
})

createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost')

  if (url.pathname === '/__reload') {
    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    })
    res.write('retry: 500\n\n')
    clients.add(res)
    req.on('close', () => clients.delete(res))
    return
  }

  let p = decodeURIComponent(url.pathname)
  if (p === '/') p = '/field.html'
  const file = join(ROOT, normalize(p).replace(/^(\.\.[/\\])+/, ''))
  if (!file.startsWith(ROOT)) { res.writeHead(403).end('forbidden'); return }

  try {
    const s = await stat(file)
    if (s.isDirectory()) throw new Error('dir')
    const ext = extname(file).toLowerCase()
    let body = await readFile(file)
    if (ext === '.html') {
      body = Buffer.from(body.toString('utf8').replace('</body>', SNIPPET + '\n</body>'))
    }
    res.writeHead(200, {
      'Content-Type': TYPES[ext] || 'application/octet-stream',
      // never let the browser hold a stale copy while you are editing
      'Cache-Control': 'no-store, no-cache, must-revalidate',
      Pragma: 'no-cache',
    })
    res.end(body)
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain' }).end('not found')
  }
}).listen(PORT, '127.0.0.1', () => {
  console.log(`preview  http://127.0.0.1:${PORT}/field.html`)
  console.log(`         http://127.0.0.1:${PORT}/chain.html`)
  console.log(`         http://127.0.0.1:${PORT}/run.html`)
  console.log(`watching ${ROOT}`)
})

